"""The hand-written adversarial cases: generated by script, valid for every setup, safe tutor history."""

import json
from pathlib import Path

from scripts.generate_adversarial_cases import CASES, build_records, bug_info

ADVERSARIAL = Path(__file__).resolve().parents[1] / "eval" / "triples_adversarial.jsonl"


def committed() -> list:
    return [json.loads(line) for line in ADVERSARIAL.read_text(encoding="utf-8").splitlines() if line.strip()]


def test_committed_cases_are_exactly_what_the_generator_produces():
    assert build_records(CASES, bug_info()) == committed()
